{"hypotheses":[
  {
    "name": "Quality-Momentum Defensive Composite",
    "mechanism": "Combining high operating profitability (OperProf) and 12-month momentum (Mom12m), while shorting illiquidity (Illiquidity), creates a composite that captures persistent earnings strength and trend, while avoiding liquidity-driven tail risk. This blend should outperform each component by balancing quality and trend signals, and minimizing crash risk associated with illiquidity.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OperProf"},
        {"weight": 1.0, "primitive": "Mom12m"},
        {"weight": -0.5, "primitive": "Illiquidity"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "Mom12m", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 1.0,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Defensive Value with Analyst Confirmation",
    "mechanism": "This composite combines book-to-market (BM) and cash flow yield (CF) with analyst forecast revision (AnalystRevision) to select value stocks with improving analyst sentiment, mitigating value traps. The interaction enhances value's efficacy by filtering for companies where fundamentals are corroborated by forward-looking information.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BM"},
        {"weight": 1.0, "primitive": "CF"},
        {"weight": 0.5, "primitive": "AnalystRevision"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "correlation", "primitive": "BM", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Procyclical Asset Growth-Momentum",
    "mechanism": "Combining asset growth (AssetGrowth) and 6-month momentum (Mom6m), conditioned on positive term spread, captures firms expanding assets during economic optimism, with price confirmation. This exploits the covariance between macro optimism, firm expansion, and near-term market trends.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AssetGrowth"},
        {"weight": 1.0, "primitive": "Mom6m"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Low-Risk Intangibles Premium",
    "mechanism": "Long intangible-rich firms (IntanCFP), hedge by shorting high realized volatility (RealizedVol) and high market beta (Beta), targets intangibles-driven growth while suppressing compensation for market and idiosyncratic risk. This should produce a premium linked to mispricing of intangible assets, robust to market swings.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "IntanCFP"},
        {"weight": -0.5, "primitive": "RealizedVol"},
        {"weight": -0.5, "primitive": "Beta"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "Beta", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.9,
    "expected_decay_half_life_months": 48
  },
  {
    "name": "Off-Season Reversal Plus Earnings Surprise",
    "mechanism": "Combining off-season reversal (MomOffSeason) with earnings surprises (EarningsSurprise) captures stocks with recent negative reversal whose fundamentals have just turned positive. This exploits underreaction to fundamental improvement after a technical washout.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "MomOffSeason"},
        {"weight": 1.0, "primitive": "EarningsSurprise"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Supply-Chain Momentum Quality Composite",
    "mechanism": "By combining supplier momentum (iomom_supp) and customer momentum (iomom_cust) with gross profits (GP), the composite captures value chains with improving fundamentals and cross-firm information diffusion, while overweighting profitable industries.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "iomom_supp"},
        {"weight": 1.0, "primitive": "iomom_cust"},
        {"weight": 0.5, "primitive": "GP"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "GP", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.95,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Analyst Value-Debt Issuance Contrarian",
    "mechanism": "Long stocks with high analyst value (AnalystValue), but short those with recent debt issuance (DebtIssuance). This bets that true value identified by analysts is more credible when not tainted by aggressive corporate leverage, counteracting the tendency for debt issuers to underperform.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AnalystValue"},
        {"weight": -1.0, "primitive": "DebtIssuance"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "correlation", "primitive": "AnalystValue", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 20
  },
  {
    "name": "Resilient Organizational Capital Growth",
    "mechanism": "Organizational capital (OrgCap) and organizational capital growth (InvestPPEInv), hedged with short-term reversal (STreversal), identifies firms investing persistently in organizational productivity while controlling for short-term market noise. The composite exploits compounding intangible capital, robust to market reversals.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": 1.0, "primitive": "InvestPPEInv"},
        {"weight": -0.5, "primitive": "STreversal"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 36
  }
]}
